// LAZY LOADING MINIFICADO
if('IntersectionObserver'in window){const images=document.querySelectorAll('img[data-src]');const imageObserver=new IntersectionObserver(function(entries,observer){entries.forEach(function(entry){if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src;img.classList.remove('lazy');observer.unobserve(img)}})});images.forEach(function(img){imageObserver.observe(img)})}
